/** Feedback uses the accepted public proposal; durable compiled proofs stay private. */
function stepIdentityDiagnostics(args:Readonly<Record<string,unknown>>){
 const seen=new Set<string>(),issues:{path:string;expected:string}[]=[];
 for(const [index,raw] of (Array.isArray(args.steps)?args.steps.slice(0,24):[]).entries()){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))continue;
  const step=raw as Record<string,unknown>;
  if(!Object.hasOwn(step,'step_id'))continue;
  if(!membershipUuid(step.step_id)||seen.has(step.step_id))issues.push({path:`steps[${index}].step_id`,expected:'unique lowercase UUIDv4'});else seen.add(step.step_id);
 }
 return issues;
}
function semanticInputDiagnostics(args:any,inspection:MemberSourceInspection){
 const issues:{dimension:string;evidence_index:number;missing:string[]}[]=[];
 const counts=new Map<string,number>();for(const d of (Array.isArray(args?.interpretations)?args.interpretations.slice(0,16):[]))if(typeof d?.dimension==='string')counts.set(d.dimension,(counts.get(d.dimension)??0)+1);
 for(const [dimension,count] of counts)if(count>1)issues.push({dimension,evidence_index:-1,missing:['single_interpretation_per_dimension']});
 for(const d of (Array.isArray(args?.interpretations)?args.interpretations.slice(0,16):[]))for(const [index,e] of (Array.isArray(d?.evidence)?d.evidence.slice(0,16):[]).entries()){
  if(!e?.source)continue;const missing=['source_id','sheet_id','row','column'].filter(k=>e.source[k]===undefined);
  if(!missing.length){
   const matches=inspection.sources.filter(s=>s.source_id===e.source.source_id),source=matches[0];
   if(matches.length!==1)missing.push('source_id_not_selected');
   else if(e.source.source_sha256!==undefined&&e.source.source_sha256!==source!.sha256)missing.push('source_sha256_mismatch');
   else{const sheets=source!.sheets.filter(s=>s.sheet_id===e.source.sheet_id),sheet=sheets[0];
    if(sheets.length!==1)missing.push('sheet_id_not_selected');
    else{const rows=sheet!.rows.filter(r=>r.row===e.source.row),row=rows[0];
     if(rows.length!==1)missing.push('row_not_found');
     else if(row!.cells.filter(c=>c.column===e.source.column).length!==1)missing.push('column_not_found');
    }
   }
  }
  if(missing.length)issues.push({dimension:typeof d.dimension==='string'?d.dimension.slice(0,50):'unknown',evidence_index:index,missing});
 }return issues;
}
